const req = $('Pedido do site').first().json;
const user = $('Quem é (login do site)').first().json;
const papeis = $input.all().map(i => i.json.role).filter(Boolean);
const ok = !!(user && user.id) && papeis.some(p => ['admin_master', 'admin', 'editor'].includes(p));
return [{ json: { autorizado: ok, email: (user && user.email) || '', acao: req.body?.acao ?? '', dados: req.body?.dados ?? {} } }];
